/**
 *  @file
 *  @ingroup PEARL_base
 *  @brief   Declaration of the class LocationGroup.
 *
 *  This header file provides the declaration of the class LocationGroup
 *  and related functions.
 **/
/*-------------------------------------------------------------------------*/


#ifndef PEARL_LOCATIONGROUP_H
#define PEARL_LOCATIONGROUP_H


#include <stdint.h>

#include <iosfwd>
#include <vector>


namespace pearl
{
// --- Forward declarations -------------------------------------------------

class Location;
class String;
class SystemNode;


/*-------------------------------------------------------------------------*/
/**
 *  @class   LocationGroup
 *  @ingroup PEARL_base
 *  @brief   %Location group definition representations.
 *
 *  Instances of the class LocationGroup provide information about logical
 *  (i.e., software-related) nodes in the system hierarchy grouping one or
 *  more Location objects (hence the name location group).  Typically, such
 *  groups represent individual UNIX/MPI processes.  %Location groups are
 *  characterized by a name, a type, a parent node (of type SystemNode) in
 *  the system hierarchy, and an optional creating location group.  In
 *  addition, one or more Location definitions can be attached to a location
 *  group.  The numerical identifiers of the individual location groups are
 *  globally defined and continuously enumerated, i.e., the ID is element
 *  of [0,@#location_groups-1].
 **/
/*-------------------------------------------------------------------------*/

class LocationGroup
{
    public:
        // --- Type definitions ----------------------------

        /// %Location group definition identifier type.
        typedef uint32_t IdType;

        /// @brief %Location group types.
        ///
        /// Every location group has a type field associated to it which
        /// encodes more specific information about the group.
        ///
        enum Type
        {
            TYPE_UNKNOWN,    ///< Unknown type, used only if no other type fits

            TYPE_ACCELERATOR, ///< Accelerator locations executed on the same device controlled by one process
            TYPE_PROCESS,     ///< %Location group referring to an UNIX/MPI process

            NUMBER_OF_TYPES    ///< Not a valid type, for internal use only
        };


        // --- Static class data ---------------------------

        /// Numerical identifier used for undefined loction group definitions.
        static const IdType NO_ID = (~static_cast< IdType >(0));

        /// Static instance of class LocationGroup representing undefined
        /// location group entries in other definitions.
        static const LocationGroup UNDEFINED;


        // --- Public methods ------------------------------

        /// @name Constructors & destructor
        /// @{

        /// @brief Constructor.
        ///
        /// Creates a new location group definition instance and initializes
        /// it with the given values.
        ///
        /// @param id
        ///     Global location group identifier
        /// @param name
        ///     Group name
        /// @param type
        ///     %Location group type
        /// @param parent
        ///     Parent node in system tree (non-NULL)
        /// @param creator
        ///     Creating location group if applicable, `nullptr` otherwise
        ///
        LocationGroup(IdType         id,
                      const String&  name,
                      Type           type,
                      SystemNode*    parent,
                      LocationGroup* creator);

        /// @brief Destructor.
        ///
        /// Releases all allocated resources and destroys the instance.
        ///
        virtual
        ~LocationGroup();

        /// @}
        /// @name Access definition data
        /// @{

        /// @brief Get global identifier.
        ///
        /// Returns the global identifier of the location group definition.
        ///
        /// @returns
        ///     Global identifier
        ///
        IdType
        getId() const;

        /// @brief Get location group name.
        ///
        /// Returns the string definition storing the location group's name.  If
        /// this information is not available, String::UNDEFINED is returned.
        ///
        /// @returns
        ///     %Location group name
        ///
        const String&
        getName() const;

        /// @brief Get location group type.
        ///
        /// Returns the location group type, encoding more detailed information.
        /// See the documentation of LocationGroup::Type for details.
        ///
        /// @returns
        ///     %Location group type
        ///
        virtual Type
        getType() const;

        /// @brief Get parent node.
        ///
        /// Returns a pointer to the parent node in the system tree.
        ///
        /// @returns
        ///     Parent node
        ///
        SystemNode*
        getParent() const;

        /// @brief Get creating location group.
        ///
        /// Returns the location group definition referring to the creating
        /// location group if applicable.  Otherwise, LocationGroup::UNDEFINED
        /// is returned.
        ///
        /// @returns
        ///     Creating location group
        ///
        const LocationGroup&
        getCreator() const;

        /// @brief Get number of locations.
        ///
        /// Returns the number of associated locations.
        ///
        /// @returns
        ///     Number of locations
        ///
        uint32_t
        numLocations() const;

        /// @brief Get location.
        ///
        /// Returns the associated location stored at the given @p index in
        /// the range [0,@#stored_locations-1].
        ///
        /// @param index
        ///     %Location index
        /// @returns
        ///     %Location
        ///
        const Location&
        getLocation(uint32_t index) const;

        /// @}


    protected:
        // --- Protected methods ---------------------------

        /// @name Stream I/O functions
        /// @{

        /// @brief Stream output helper function.
        ///
        /// Prints the location group's attributes to the given @p stream.
        /// This member function is triggered by the stream output operator.
        ///
        /// @param stream
        ///     Output stream
        /// @returns
        ///     Output stream
        ///
        virtual std::ostream&
        output(std::ostream& stream) const;

        /// @}


    private:
        // --- Type definitions ----------------------------

        /// Container type for child locations
        typedef std::vector< Location* > ChildContainer;


        // --- Data members --------------------------------

        /// Global identifier
        IdType mIdentifier;

        /// Location group name
        const String& mName;

        /// Parent node in system tree
        SystemNode* mParent;

        /// Creating location group
        LocationGroup* mCreator;

        /// Associated locations
        ChildContainer mLocations;

        /// %Location group type
        Type mType;


        // --- Private methods & friends -------------------

        void
        addLocation(Location* location);


        friend class Location;

        friend std::ostream&
        operator<<(std::ostream&        stream,
                   const LocationGroup& item);
};


// --- Related functions ----------------------------------------------------

/// @name Stream I/O functions
/// @{

/// @brief   Stream output operator.
/// @relates LocationGroup
///
/// Prints the contents of the given location group definition object @p item
/// to an output @p stream in a human-readable form.
///
/// @param stream
///     Output stream
/// @param item
///     %Location group definition object
/// @returns
///     Output stream
///
std::ostream&
operator<<(std::ostream&        stream,
           const LocationGroup& item);

/// @brief   Stream output operator.
/// @relates LocationGroup
///
/// Prints the contents of the given location group type @p item to an output
/// @p stream in a human-readable form.
///
/// @param stream
///     Output stream
/// @param item
///     %Location group type
/// @returns
///     Output stream
///
std::ostream&
operator<<(std::ostream&       stream,
           LocationGroup::Type item);

/// @}
/// @name Comparison operators
/// @{

/// @brief   Equality operator.
/// @relates LocationGroup
///
/// Compares two location group definition objects @p lhs and @p rhs for
/// equality.  Two groups are considered equal if their identifiers, names,
/// types, parents, and creators are identical.  The child nodes are not
/// compared, i.e., this operator performs a "shallow" comparison.
///
/// @param lhs
//      Left-hand operand
/// @param rhs
///     Right-hand operand
/// @returns
///     True if the location group definitions are equal, false otherwise.
///
bool
operator==(const LocationGroup& lhs,
           const LocationGroup& rhs);

/// @brief   Inequality operator.
/// @relates LocationGroup
///
/// Compares two location group definition objects @p lhs and @p rhs for
/// inequality.  Two groups are considered unequal if either their IDs, names,
/// types, parentsi, or creators differ.  The child nodes are not compared,
/// i.e., this operator performs a "shallow" comparison.
///
/// @param lhs
///     Left-hand operand
/// @param rhs
///     Right-hand operand
/// @returns
///     True if the location group definitions differ, false otherwise.
///
bool
operator!=(const LocationGroup& lhs,
           const LocationGroup& rhs);

/// @}
}    // namespace pearl


#endif    // !PEARL_LOCATIONGROUP_H

