/*-------------------------------------------------------------------------*/
/**
 *  @brief   Helper struct defining collective operation type enumerators.
 *  @ingroup PEARL_base
 *
 *  The CollectiveOpType_enum helper struct defines the enumerators provided
 *  by the scoped enumeration CollectiveOpType.  It is passed as a base class
 *  to the ScopedEnum class template.
 **/
/*-------------------------------------------------------------------------*/

struct CollectiveOpType_enum
{
    /// @brief Collective operation types.
    ///
    /// The scoped enumeration CollectiveOpType provides symbolic names for
    /// different types of collective operations.  These are used by a
    /// number of collective event representations to specify the measured
    /// operation in more detail.
    ///
    enum type
    {
        ALLGATHER,                     ///< Gather data from all to all group members (same count)
        ALLGATHERV,                    ///< Gather data from all to all group members (varying count)
        ALLOCATE,                      ///< Memory allocation
        ALLREDUCE,                     ///< Reduction from all to all group members
        ALLTOALL,                      ///< Combined scatter/gather operation (same count)
        ALLTOALLV,                     ///< Combined scatter/gather operation (varying count)
        ALLTOALLW,                     ///< Combined scatter/gather operation (varying count and data type)
        BARRIER,                       ///< Barrier synchronization
        BCAST,                         ///< Broadcast data from one to all group members
        CREATE_HANDLE,                 ///< Handle creation
        CREATE_HANDLE_AND_ALLOCATE,    ///< Combined handle creation and memory allocation
        DEALLOCATE,                    ///< Memory deallocation
        DESTROY_HANDLE,                ///< Handle destruction
        DESTROY_HANDLE_AND_DEALLOCATE, ///< Combined handle destruction and memory deallocation
        EXSCAN,                        ///< Prefix reduction excluding receiving group member
        GATHER,                        ///< Gather data from all to one group member (same count)
        GATHERV,                       ///< Gather data from all to one group member (varying count)
        REDUCE,                        ///< Reduction from all to one group member
        REDUCE_SCATTER,                ///< Combined reduce/scatter operation (varying count)
        REDUCE_SCATTER_BLOCK,          ///< Combined reduce/scatter operation (same count)
        SCAN,                          ///< Prefix reduction including receiving group member
        SCATTER,                       ///< Scatter data from one to all group members (same count)
        SCATTERV                       ///< Scatter data from one to all group members (varying count)
    };
};


/// @copydoc CollectiveOpType_enum::type
/// See CollectiveOpType_enum::type for details.
typedef ScopedEnum< CollectiveOpType_enum > CollectiveOpType;


