/**
 * @struct  EventKeyCompare
 * @ingroup PEARL_base
 * @brief   Provides a comparison operator that allows Event objects to be
 *          as key in std::map or std::set
 */
/*-------------------------------------------------------------------------*/

struct EventKeyCompare
{
    bool
    operator()(const Event& lhs,
               const Event& rhs) const
