 *  related functions.
 **/
/*-------------------------------------------------------------------------*/


#ifndef PEARL_COMMUNICATOR_H
#define PEARL_COMMUNICATOR_H


#include <stdint.h>

#include <iosfwd>

#include <pearl/Flags.h>
#include <pearl/Paradigm.h>


namespace pearl
{
// --- Forward declarations -------------------------------------------------

class CommSet;
class String;


/*-------------------------------------------------------------------------*/
/**
 *  @class   Communicator
 *  @ingroup PEARL_base
 *  @brief   Representation of a communicator definition.
 *
 *  Instances of the Communicator definition class provide information about
 *  communication contexts.  Communicators are characterized by an identifier,
 *  a name, a set of property flags, a parent communicator, and an associated
 *  group of locations (the communication set).
 **/
/*-------------------------------------------------------------------------*/

class Communicator
{
    public:
        // --- Type definitions ----------------------------

        /// %Communicator definition identifier type.
        typedef uint32_t IdType;


        /// @brief %Communicator properties.
        ///
        /// Symbolic names for flags indicating certain properties of a
        /// communicator definition.
        ///
        enum Property
        {
            /// %Communicator without special properties
            PROPERTY_NONE = 0,

            /// Indicates that handle creation/destruction events exist for
            /// the communicator
            PROPERTY_CREATE_DESTROY_EVENTS = (1 << 0)
        };


        /// %Communicator property flags type.
        typedef Flags< Property, uint8_t > Properties;


        // --- Static class data ---------------------------

        /// Numerical identifier used for undefined communicator definitions.
        static const IdType NO_ID = (~static_cast< IdType >(0));

        /// Static instance of class Communicator representing undefined
        /// communicator entries in other definitions.
        static const Communicator UNDEFINED;


        // --- Public methods ------------------------------

        /// @name Constructors & destructor
        /// @{

        /// @brief Constructor.
        ///
        /// Creates a new instance with the given global identifier @p id,
        /// communicator @p name, @p properties, associated communication
        /// set @p commSet, and a @p parent communicator.
        ///
        /// @param id
        ///     Global communicator identifier
        /// @param name
        ///     Communicator name
        /// @param commSet
        ///     Associated communication set
        /// @param properties
        ///     Property flags
        /// @param parent
        ///     Parent communicator (`nullptr` for root communicators or when
        ///     this information is not available)
        ///
        /// @exception_nothrow
        ///
        Communicator(IdType              id,
                     const String&       name,
                     Properties          properties,
                     const CommSet&      commSet,
                     const Communicator* parent);

        /// @brief Destructor.
        ///
        /// Destroys the communicator instance.
        ///
        /// @exception_nothrow
        ///
        virtual
        ~Communicator();

        /// @}
        /// @name Query functions
        /// @{

        /// @brief Get global identifier.
        ///
        /// Returns the global identifier of the communicator definition.
        ///
        /// @returns
        ///     Global identifier
        ///
        /// @exception_nothrow
        ///
        IdType
        getId() const;

        /// @brief Get communicator name.
        ///
        /// Returns a constant reference to the string definition storing the
        /// communicators's name.  If this information is not available,
        /// String::UNDEFINED is returned.
        ///
        /// @returns
        ///     Communicator name
        ///
        /// @exception_nothrow
        ///
        const String&
        getName() const;

        /// @brief Get associated communication set.
        ///
        /// Returns a constant reference to the associated communication set.
        ///
        /// @returns
        ///     Associated communication set
        ///
        /// @exception_nothrow
        ///
        const CommSet&
        getCommSet() const;

        /// @brief Get parent communicator.
        ///
        /// Returns a pointer to the parent communicator if applicable.
        /// Returns `nullptr` for root communicators or when this information
        /// is not available.
        ///
        /// @returns
        ///     Parent communicator
        ///
        /// @exception_nothrow
        ///
        const Communicator*
        getParent() const;

        /// @brief Get  communicator properties.
        ///
        /// Returns the property flags of the communicator.
        ///
        /// @returns
        ///     Property flags
        ///
        Properties
        getProperties() const;

        /// @brief Get size.
        ///
        /// Returns the size of this communicator (i.e., the number of ranks
        /// in the associated communication set).
        ///
        /// @returns
        ///     %Communicator size
        ///
        /// @exception_nothrow
        ///
        uint32_t
        getSize() const;

        /// @brief Get paradigm.
        ///
        /// Returns the paradigm associated to this communicator.
        ///
        /// @returns
        ///     Communication paradigm
        ///
        /// @exception_nothrow
        ///
        Paradigm
        getParadigm() const;

        /// @}


    private:
