            CbData(uint32_t            remote,
                   const Communicator& comm,
                   bool                ensureSynchronous = false)
                : mRemote(remote),
                  mComm(comm),
                  mEnsureSynchronous(ensureSynchronous)
            {
            }

            uint32_t            mRemote;
            const Communicator& mComm;
            bool                mEnsureSynchronous;
        };


        /// @name Constructors & destructors
        /// @{

